import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as escape from "./escape.ts";
import * as escapeEncode from "./escape_encode.ts";
import * as unescStr from "./unesc_str.ts";
import * as entity from "./entity.ts";
import * as conv from "../runtime/conv.ts";
import * as utf8 from "../runtime/utf8.ts";

// Vectors are generated by ts/tools/gen-html-vectors from Go's real html package.
// Byte slices are lowercase hex, "" is an empty slice and null is a Go nil slice.
// Strings are JSON strings (valid UTF-8 only). Functions that Go calls through a
// linkname (unexported in Go) are listed under their Go names. Each vector is an
// array: [args, ret], [args, null, true] for a Go panic, or [args, ret, false, after]
// for an in-place call (see vec.MarshalJSON in the generator).
//
// Where a Go result is nil (null) and the TypeScript result is an empty array, the
// two are accepted as equal, except for functions whose nil-ness is typed (UnescapeBytes):
// Go's nil and empty slices are not distinguished by the non-nullable functions.

interface GoCase {
  args: unknown[];
  ret: unknown;
  panic: boolean;
  after?: string | null;
}

interface Vectors {
  goVersion: string;
  badEntity: string;
  entityCount: number;
  entities: { name: string; cps: string }[];
  functions: Record<string, GoCase[]>;
}

// rawVectors is the file as written by the generator: each vector is an array.
interface RawVectors extends Omit<Vectors, "functions"> {
  functions: Record<string, unknown[][]>;
}

function toCase(v: unknown[]): GoCase {
  return {
    args: v[0] as unknown[],
    ret: v[1],
    panic: v[2] === true,
    after: v.length > 3 ? (v[3] as string) : undefined,
  };
}

const raw: RawVectors = JSON.parse(
  readFileSync(new URL("./testdata/escape_vectors.json", import.meta.url), "utf8")
);
const data: Vectors = { ...raw, functions: {} };
for (const [name, vs] of Object.entries(raw.functions)) {
  data.functions[name] = vs.map(toCase);
}

function fromHex(h: string): Uint8Array {
  return new Uint8Array(Buffer.from(h, "hex"));
}

function argBytes(v: unknown): Uint8Array | null {
  if (v === null) {
    return null;
  }
  return fromHex(v as string);
}

function toHex(b: Uint8Array | null): string | null {
  if (b === null) {
    return null;
  }
  return Buffer.from(b).toString("hex");
}

// fnVectors returns the vectors of one function, failing the test when there are none.
function fnVectors(name: string): GoCase[] {
  const vs = data.functions[name];
  assert.ok(vs !== undefined && vs.length > 0, "no vectors for " + name);
  return vs;
}

// inputValid reports whether the first argument of a vector is valid UTF-8. A nil
// input is valid (there is nothing to decode).
function inputValid(v: GoCase): boolean {
  const b = argBytes(v.args[0]);
  return b === null || utf8.Valid(b);
}

// lossyWant is the Go result after the lossy round trip that a JS string applies to
// invalid UTF-8: conv.BytesFromString(conv.StringFromBytes(goOutput)). A nil result stays nil.
function lossyWant(v: GoCase): GoCase {
  const ret = v.ret as string | null;
  if (ret === null) {
    return v;
  }
  const lossy = conv.BytesFromString(conv.StringFromBytes(fromHex(ret)));
  return { ...v, ret: toHex(lossy) };
}

// runCases calls check for every vector of name that pick accepts and reports every mismatch.
function runCases(
  name: string,
  check: (v: GoCase) => string | null,
  pick: (v: GoCase) => boolean = () => true
): void {
  const vs = fnVectors(name).filter(pick);
  assert.ok(vs.length > 0, "no vectors for " + name + " after filtering");
  const failures: string[] = [];
  for (const v of vs) {
    let msg: string | null = null;
    try {
      msg = check(v);
    } catch (e) {
      msg = "threw " + String(e);
    }
    if (msg !== null) {
      failures.push(name + " " + JSON.stringify(v.args) + ": " + msg);
    }
  }
  assert.equal(failures.length, 0, failures.slice(0, 20).join("\n") + "\n(" + failures.length + " failures of " + vs.length + ")");
}

// expectStr checks a string result against the Go result.
function expectStr(got: string, v: GoCase): string | null {
  return got === v.ret ? null : "got " + JSON.stringify(got) + " want " + JSON.stringify(v.ret);
}

// expectBytes checks a byte-slice result. nullable is true for the functions whose
// result is nil exactly when the input is nil.
function expectBytes(got: Uint8Array | null, v: GoCase, nullable: boolean): string | null {
  const hex = toHex(got);
  if (v.ret === null && !nullable && hex === "") {
    return null;
  }
  return hex === v.ret ? null : "got " + JSON.stringify(hex) + " want " + JSON.stringify(v.ret);
}

// expectPanic checks that a Go panic is also a throw in TypeScript.
function expectPanic(v: GoCase, fn: () => unknown): string | null {
  let threw = false;
  try {
    fn();
  } catch {
    threw = true;
  }
  return threw === v.panic ? null : "panic mismatch: go panic " + v.panic + ", ts threw " + threw;
}

test("Go version and entity table counts", () => {
  assert.equal(data.entityCount, data.entities.length);
  const m = entity.entityMap();
  assert.equal(m.size, data.entityCount, "entry count");
  const bad: string[] = [];
  for (const e of data.entities) {
    const want = e.cps
      .split(",")
      .map((h) => String.fromCodePoint(parseInt(h, 16)))
      .join("");
    const got = m.get(e.name);
    if (got !== want) {
      bad.push(e.name + ": got " + JSON.stringify(got) + " want " + JSON.stringify(want));
    }
    if (entity.lookupEntity(e.name) !== want) {
      bad.push(e.name + ": lookupEntity mismatch");
    }
  }
  assert.deepEqual(bad.slice(0, 20), []);
  assert.equal(entity.lookupEntity("NoSuchEntity;"), "");
  assert.equal(entity.lookupEntity("AElig"), "", "keys carry the semicolon");
  assert.equal(unescStr.BadEntity, Buffer.from(data.badEntity, "hex").toString("utf8"), "BadEntity");
});

test("EscapeString", () => {
  runCases("EscapeString", (v) => expectStr(escape.EscapeString(v.args[0] as string), v));
});

test("UnescapeString", () => {
  runCases("UnescapeString", (v) => expectStr(escape.UnescapeString(v.args[0] as string), v));
});

test("EscapeHTMLStr", () => {
  runCases("EscapeHTMLStr", (v) => expectStr(escapeEncode.EscapeHTMLStr(v.args[0] as string), v));
});

test("UnescapeHTMLStr", () => {
  runCases("UnescapeHTMLStr", (v) => expectStr(escapeEncode.UnescapeHTMLStr(v.args[0] as string), v));
});

test("EscapeAttrVal", () => {
  runCases("EscapeAttrVal", (v) => expectStr(escapeEncode.EscapeAttrVal(v.args[0] as string), v));
});

test("UnescapeAttrVal", () => {
  runCases("UnescapeAttrVal", (v) => expectStr(escapeEncode.UnescapeAttrVal(v.args[0] as string), v));
});

test("HtmlUnescapeString", () => {
  runCases("HtmlUnescapeString", (v) => expectStr(unescStr.HtmlUnescapeString(v.args[0] as string), v));
});

test("EscapeHTML", () => {
  runCases("EscapeHTML", (v) => {
    const arg = argBytes(v.args[0]) ?? new Uint8Array(0);
    return expectBytes(escapeEncode.EscapeHTML(arg), v, false);
  });
});

// Invalid UTF-8 input: a JS string cannot hold it, so the port returns Go's output
// after the lossy round trip (conv.StringFromBytes turns each invalid byte into U+FFFD).
// Valid UTF-8 input must match Go byte for byte, so the two groups are separate tests.
test("UnescapeHTML (valid UTF-8 input)", () => {
  runCases(
    "UnescapeHTML",
    (v) => {
      const arg = argBytes(v.args[0]) ?? new Uint8Array(0);
      return expectBytes(escapeEncode.UnescapeHTML(arg), v, false);
    },
    inputValid
  );
});

test("UnescapeHTML (invalid UTF-8 input, lossy)", () => {
  runCases(
    "UnescapeHTML",
    (v) => {
      const arg = argBytes(v.args[0]) ?? new Uint8Array(0);
      return expectBytes(escapeEncode.UnescapeHTML(arg), lossyWant(v), false);
    },
    (v) => !inputValid(v)
  );
});

test("UnescapeBytes (valid UTF-8 input)", () => {
  runCases(
    "UnescapeBytes",
    (v) => expectBytes(unescStr.UnescapeBytes(argBytes(v.args[0])), v, true),
    inputValid
  );
});

test("UnescapeBytes (invalid UTF-8 input, lossy)", () => {
  // Same lossy comparison as UnescapeHTML above (see the comment there).
  runCases(
    "UnescapeBytes",
    (v) => expectBytes(unescStr.UnescapeBytes(argBytes(v.args[0])), lossyWant(v), true),
    (v) => !inputValid(v)
  );
});

