test("parseEntity (unexported in Go)", () => {
  runCases("parseEntity", (v) => {
    const [s, n] = unescStr.parseEntity(v.args[0] as string);
    const want = v.ret as [string, number];
    return s === want[0] && n === want[1] ? null : "got " + JSON.stringify([s, n]) + " want " + JSON.stringify(want);
  });
});

test("isValidEntityCode (unexported in Go)", () => {
  runCases("isValidEntityCode", (v) => {
    const got = unescStr.isValidEntityCode(v.args[0] as number);
    return got === v.ret ? null : "got " + got + " want " + v.ret;
  });
});

test("unescape (unexported in Go, in place)", () => {
  runCases("unescape", (v) => {
    const buf = argBytes(v.args[0]) ?? new Uint8Array(0);
    const out = escape.unescape(buf, v.args[1] as boolean);
    return expectBytes(out, v, false) ?? (toHex(buf) === v.after ? null : "after " + toHex(buf) + " want " + v.after);
  });
});

test("lower (unexported in Go, in place)", () => {
  runCases("lower", (v) => {
    const buf = argBytes(v.args[0]) ?? new Uint8Array(0);
    const out = escape.lower(buf);
    return expectBytes(out, v, false) ?? (toHex(buf) === v.after ? null : "after " + toHex(buf) + " want " + v.after);
  });
});

test("unescapeEntity (unexported in Go, in place)", () => {
  runCases("unescapeEntity", (v) => {
    const buf = argBytes(v.args[0]) ?? new Uint8Array(0);
    const [d, s] = escape.unescapeEntity(buf, v.args[1] as number, v.args[2] as number, v.args[3] as boolean);
    const want = v.ret as [number, number];
    if (d !== want[0] || s !== want[1]) {
      return "got " + JSON.stringify([d, s]) + " want " + JSON.stringify(want);
    }
    return toHex(buf) === v.after ? null : "after " + toHex(buf) + " want " + v.after;
  });
});

test("unhex (unexported in Go, panics on non-hex)", () => {
  runCases("unhex", (v) => {
    const b = v.args[0] as number;
    if (v.panic) {
      return expectPanic(v, () => escapeEncode.unhex(b));
    }
    const got = escapeEncode.unhex(b);
    return got === v.ret ? null : "got " + got + " want " + v.ret;
  });
});

test("advance (unexported in Go)", () => {
  runCases("advance", (v) => {
    const buf = argBytes(v.args[0]) ?? new Uint8Array(0);
    const [b, p] = escapeEncode.advance(buf, v.args[1] as number);
    const want = v.ret as [number, number];
    return b === want[0] && p === want[1] ? null : "got " + JSON.stringify([b, p]) + " want " + JSON.stringify(want);
  });
});
